//! Platform-independent concealed-content decisions.
//! The native adapters feed these functions the pasteboard types / clipboard
//! format names and decide before any content data is read.

pub const MACOS_MARKERS: [&str; 3] = [
    "org.nspasteboard.ConcealedType",
    "org.nspasteboard.TransientType",
    "org.nspasteboard.AutoGeneratedType",
];

const WINDOWS_EXCLUDE_FORMATS: [&str; 2] = [
    "ExcludeClipboardContentFromMonitorProcessing",
    "Clipboard Viewer Ignore",
];

const WINDOWS_DWORD_FORMATS: [&str; 2] = ["CanIncludeInClipboardHistory", "CanUploadToCloudClipboard"];

pub fn macos_is_concealed<S: AsRef<str>>(types: &[S]) -> bool {
    types.iter().any(|t| MACOS_MARKERS.contains(&t.as_ref()))
}

/// `names` are the registered format names present on the clipboard.
/// `read_dword` fetches the raw payload of a named format (only called for the
/// two boolean-flag formats, and only when present).
pub fn windows_is_concealed<S: AsRef<str>>(
    names: &[S],
    read_dword: impl Fn(&str) -> Option<Vec<u8>>,
) -> bool {
    if names.iter().any(|n| WINDOWS_EXCLUDE_FORMATS.contains(&n.as_ref())) {
        return true;
    }
    names
        .iter()
        .map(|n| n.as_ref())
        .filter(|n| WINDOWS_DWORD_FORMATS.contains(n))
        .any(|n| matches!(read_dword(n).as_deref(), Some([0, 0, 0, 0])))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn macos_markers_are_concealed() {
        for m in MACOS_MARKERS {
            assert!(macos_is_concealed(&["public.utf8-plain-text", m]));
        }
    }

    #[test]
    fn macos_plain_text_is_not_concealed() {
        assert!(!macos_is_concealed(&["public.utf8-plain-text", "public.html"]));
        assert!(!macos_is_concealed::<&str>(&[]));
    }

    #[test]
    fn windows_exclude_formats_are_concealed() {
        let none = |_: &str| None;
        assert!(windows_is_concealed(&["ExcludeClipboardContentFromMonitorProcessing"], none));
        assert!(windows_is_concealed(&["Clipboard Viewer Ignore"], none));
    }

    #[test]
    fn windows_zero_dword_flags_are_concealed() {
        let zero = |_: &str| Some(vec![0, 0, 0, 0]);
        assert!(windows_is_concealed(&["CanIncludeInClipboardHistory"], zero));
        assert!(windows_is_concealed(&["CanUploadToCloudClipboard"], zero));
    }

    #[test]
    fn windows_nonzero_or_malformed_flags_are_not_concealed() {
        assert!(!windows_is_concealed(&["CanIncludeInClipboardHistory"], |_| Some(vec![1, 0, 0, 0])));
        assert!(!windows_is_concealed(&["CanUploadToCloudClipboard"], |_| Some(vec![0, 0])));
        assert!(!windows_is_concealed(&["CanUploadToCloudClipboard"], |_| None));
    }

    #[test]
    fn windows_absent_flag_formats_are_not_read() {
        assert!(!windows_is_concealed(&["CF_UNICODETEXT"], |_| panic!("must not read")));
    }
}
